const body = ($input.first().json.body) || {};

const required = ["analysis_id", "input_type", "description"];
const missing = required.filter((f) => body[f] === undefined || body[f] === null || String(body[f]).trim() === "");
if (missing.length) {
  throw new Error("Missing required field(s): " + missing.join(", "));
}

const input_hash = " ";

return [{
  json: {
    analysis_request_id: body.analysis_id,
    input_type: body.input_type,
    description: body.description,
    input_hash,
  },
}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const ai = JSON.parse($json.choices[0].message.content);

return [
  {
    json: {
      analysis_request_id: $('Validate & Prepare').first().json.analysis_request_id,
      input_type: $('Validate & Prepare').first().json.input_type,
      description: $('Validate & Prepare').first().json.description,
      input_hash: $('Validate & Prepare').first().json.input_hash,

      ...ai
    }
  }
];
